a = {i: 2*i for i in range(100)}
b = a.copy()
for i in range(100):
    print(i, b[i])
print(len(b))

for d in {}, {42:2}:
    print(d.get(42))
    print(d.get(42,2))

d = {1: 2, 3: 4}
print(d.pop(3), d)
print(d)
print(d.pop(1, 42), d)
print(d.pop(1, 42), d)
print(d.pop(1, None), d)
try:
    print(d.pop(1), "!!!")
except KeyError:
    print("Raised KeyError")
else:
    print("Did not raise KeyError!")

d = {1: 2}
for m in d.items, d.values, d.keys:
    print(m())
    print(list(m()))

# print a view with more than one item
print({1:1, 2:1}.values())

# `bool` and `len` unary ops
for d in ({}, {1: 2}, {1: 2, 3: 4}):
    for op in (bool, len):
        print(op(d.keys()), op(d.values()), op(d.items()))

# unsupported binary op on a dict values view
try:
    {1:1}.values() + 1
except TypeError:
    print('TypeError')

# unsupported binary op on a dict keys view
try:
    {1:1}.keys() + 1
except TypeError:
    print('TypeError')

# keys dict_view is not hashable

try:
    hash({}.keys())
except TypeError:
    print('TypeError')

# values dict_view is hashable

print(type(hash({}.values())))

# items dict_view is not hashable

try:
    hash({}.items())
except TypeError:
    print('TypeError')

# set operations still to come

